import numpy as np
import sys
import os

def get_active_sets(centers, radii, tol=1e-8):
    N = centers.shape[0]
    boundary_set = set()
    wall_map = {0: 'xmin', 1: 'xmax', 2: 'ymin', 3: 'ymax'}
    for i in range(N):
        if abs(centers[i,0] - radii[i]) <= tol: boundary_set.add((i, wall_map[0]))
        if abs(1 - centers[i,0] - radii[i]) <= tol: boundary_set.add((i, wall_map[1]))
        if abs(centers[i,1] - radii[i]) <= tol: boundary_set.add((i, wall_map[2]))
        if abs(1 - centers[i,1] - radii[i]) <= tol: boundary_set.add((i, wall_map[3]))

    active_pairs = set()
    for i in range(N):
        for j in range(i + 1, N):
            dist = np.linalg.norm(centers[i] - centers[j])
            if abs(dist - (radii[i] + radii[j])) <= tol:
                active_pairs.add(tuple(sorted((i, j))))
    return boundary_set, active_pairs

def construct_packing():
    """
    Loads known SOTA packings using verified paths and computes the consensus graph.
    """
    N = 26
    packings = {}

    try:
        # Paths verified via `storage list`
        packings['Aletheia'] = (np.loadtxt("storage/Aletheia/sota_2_centers.txt"), np.loadtxt("storage/Aletheia/sota_2_radii.txt"))
        packings['Noesis'] = (np.loadtxt("storage/Noesis/latest_centers.txt"), np.loadtxt("storage/Noesis/latest_radii.txt"))
        packings['Scientia'] = (np.loadtxt("storage/Scientia/nmap/n26/centers.txt"), np.loadtxt("storage/Scientia/nmap/n26/radii.txt"))
    except Exception as e:
        print(f"ERROR loading one or more peer SOTA packings: {e}", file=sys.stderr)
        return np.zeros((N,2)), np.zeros(N)

    all_boundary_sets = []
    all_pair_sets = []

    for name, (centers, radii) in packings.items():
        boundary_set, pair_set = get_active_sets(centers, radii)
        all_boundary_sets.append(boundary_set)
        all_pair_sets.append(pair_set)
        print(f"Processed {name}: {len(boundary_set)} boundary contacts, {len(pair_set)} pair contacts.", file=sys.stdout)

    consensus_boundary = set.intersection(*all_boundary_sets)
    consensus_pairs = set.intersection(*all_pair_sets)

    print(f"\n--- 3-WAY CONSENSUS GRAPH (Aletheia, Noesis, Scientia) ---", file=sys.stdout)
    print(f"Consensus Boundary Contacts: {len(consensus_boundary)}", file=sys.stdout)
    print(f"Consensus Pair Contacts: {len(consensus_pairs)}", file=sys.stdout)

    os.makedirs("storage/Aletheia/consensus", exist_ok=True)
    # Saving as string to handle the mixed data types in boundary set
    with open("storage/Aletheia/consensus/boundary_3way_consensus.txt", "w") as f:
        for item in consensus_boundary:
            f.write(f"{item[0]},{item[1]}\n")
    np.savetxt("storage/Aletheia/consensus/pairs_3way_consensus.txt", np.array(list(consensus_pairs)), fmt='%d')
    print("Consensus graph saved to storage/Aletheia/consensus/", file=sys.stdout)

    return packings['Aletheia'][0], packings['Aletheia'][1] * (1.0 - 1e-9)
